    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (5,1,'alcohol-driving','multiple_choice','What is the legal blood alcohol concentration limit in Nigeria?','["0.08%","0.05%","0.02%","0.00%"]',3,'Nigeria has zero tolerance. Any detectable alcohol is an offence.',1,true),
    (5,1,'alcohol-driving','multiple_choice','How does alcohol affect driving?','["Improves focus","Slows reaction time and impairs judgement","No effect","Makes you more alert"]',1,'Alcohol slows reaction time, impairs judgement, and reduces coordination.',1,true),
    (5,1,'alcohol-driving','multiple_choice','How long does it take for the body to process one unit of alcohol?','["30 minutes","About 1 hour","2 hours","10 minutes"]',1,'The body processes about one unit of alcohol per hour. Time is the only way to sober up.',2,true),
    (5,1,'alcohol-driving','multiple_choice','Which of these is affected by alcohol?','["Reaction time","Judgement","Coordination","All of the above"]',3,'Alcohol affects reaction time, judgement, coordination, and vision.',1,true),
    (5,1,'alcohol-driving','multiple_choice','Does coffee or a cold shower sober you up?','["Yes","No — only time works","Sometimes","Only coffee"]',1,'No. Only time allows the body to process alcohol. Coffee and showers do not reduce blood alcohol.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the penalty for drink driving in Nigeria?','["Warning","Fine, imprisonment, or both","License suspension only","No penalty"]',1,'Drink driving can result in a fine, imprisonment, or both. License may also be suspended.',2,true),
    (5,1,'alcohol-driving','multiple_choice','How many drinks can you have before driving?','["One","Two","None — zero tolerance in Nigeria","Three"]',2,'Nigeria has zero tolerance. No amount of alcohol is legal before driving.',1,true),
    (5,1,'alcohol-driving','multiple_choice','What is a standard drink?','["Any glass","12 oz beer, 5 oz wine, or 1.5 oz spirits","A full bottle","Any amount"]',1,'A standard drink is 12 oz beer (5%), 5 oz wine (12%), or 1.5 oz spirits (40%).',2,true),
    (5,1,'alcohol-driving','multiple_choice','What does BAC stand for?','["Blood Alcohol Concentration","Breath Alcohol Content","Body Alcohol Count","Blood Analysis Check"]',0,'BAC = Blood Alcohol Concentration. Measures alcohol in the bloodstream.',1,true),
    (5,1,'alcohol-driving','multiple_choice','What is a breathalyser?','["A breathing device","A device that measures alcohol in breath","A medical tool","A car part"]',1,'A breathalyser measures the alcohol content in your breath to estimate BAC.',1,true),
    (5,1,'alcohol-driving','multiple_choice','Can FRSC use a breathalyser on you?','["No","Yes — at checkpoints and after accidents","Only with a warrant","Only if you agree"]',1,'Yes. FRSC can test you at checkpoints or after an accident. Refusing is an offence.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What happens if you refuse a breathalyser test?','["Nothing","It is treated as a positive result — an offence","You get a warning","You can drive away"]',1,'Refusing a breathalyser is treated as failing the test. It is an offence.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the effect of alcohol on your vision?','["Improves it","Blurred vision and reduced peripheral awareness","No effect","Better night vision"]',1,'Alcohol causes blurred vision and reduces peripheral awareness.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the effect of alcohol on reaction time?','["Faster","Slower","No effect","Improved"]',1,'Alcohol significantly slows reaction time. You react more slowly to hazards.',1,true),
    (5,1,'alcohol-driving','multiple_choice','What is the effect of alcohol on confidence?','["Reduces it","Increases false confidence — more risk taking","No effect","Makes you cautious"]',1,'Alcohol increases false confidence, leading to more risk-taking behaviour.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the effect of alcohol on coordination?','["Improves it","Impairs coordination","No effect","Better balance"]',1,'Alcohol impairs coordination. Steering and pedal control become less precise.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the safest option if you plan to drink?','["Drive slowly","Do not drive — use a designated driver or taxi","Drink less","Eat before driving"]',1,'Do not drive. Use a designated driver, taxi, or ride-hailing service.',1,true),
    (5,1,'alcohol-driving','multiple_choice','What is a designated driver?','["The fastest driver","Someone who does not drink and drives others home","A professional driver","The car owner"]',1,'A designated driver is someone who agrees not to drink and drives others home safely.',1,true),
    (5,1,'alcohol-driving','multiple_choice','Can you still be over the limit the morning after drinking?','["No","Yes — alcohol stays in the body for hours","Only if you drank a lot","Only if you did not eat"]',1,'Yes. You can still be over the limit the morning after heavy drinking.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What factors affect how quickly alcohol is absorbed?','["Food, weight, gender, age","Only food","Only weight","Nothing"]',0,'Food, body weight, gender, age, and metabolism all affect alcohol absorption.',2,true),
    (5,1,'alcohol-driving','multiple_choice','Does eating food reduce your BAC?','["Yes","No — it may slow absorption but does not reduce BAC","Sometimes","Only fatty foods"]',1,'Eating slows absorption but does not reduce the total alcohol in your system.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the effect of mixing alcohol with energy drinks?','["Safe","Dangerous — masks the feeling of intoxication","Improves driving","No effect"]',1,'Energy drinks mask the feeling of being drunk, leading to overconfidence and risk-taking.',3,true),
    (5,1,'alcohol-driving','multiple_choice','What is binge drinking?','["Drinking slowly","Drinking many units in a short period","Drinking water","Drinking with food"]',1,'Binge drinking is consuming many units in a short period. Extremely dangerous.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the risk of drink driving for young drivers?','["Lower risk","Higher risk — less experience combined with impairment","Same as older drivers","No risk"]',1,'Young drivers are at higher risk. Less driving experience combined with impairment is deadly.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What percentage of road accidents involve alcohol?','["5%","20-30% globally","50%","1%"]',1,'Globally, approximately 20-30% of road accidents involve alcohol.',2,true),
    (5,1,'alcohol-driving','multiple_choice','What is the effect of alcohol on risk perception?','["Improves it","Reduces ability to perceive risk","No effect","Heightens awareness"]',1,'Alcohol reduces the ability to perceive and assess risk. Dangerous situations seem less threatening.',2,true),
    (5,2,'alcohol-driving','multiple_choice','Which drugs can impair driving?','["Only illegal drugs","Prescription, over-the-counter, and illegal drugs","Only sleeping pills","Only cannabis"]',1,'All types of drugs can impair driving: prescription, over-the-counter, and illegal.',1,true),
    (5,2,'alcohol-driving','multiple_choice','Can prescription drugs affect your driving?','["No","Yes — many cause drowsiness or dizziness","Only antibiotics","Only painkillers"]',1,'Yes. Many prescription drugs cause drowsiness, dizziness, or impaired judgement.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What should you check before taking medication and driving?','["Nothing","Read the label for driving warnings","Only the dose","Only the expiry date"]',1,'Read the label or ask your doctor if the medication affects driving.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of cannabis on driving?','["Improves it","Impairs coordination, reaction time, and attention","No effect","Makes you more alert"]',1,'Cannabis impairs coordination, reaction time, and attention. Driving under the influence is illegal.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of cocaine on driving?','["Improves it","Aggressive driving, overconfidence, and impaired judgement","No effect","Makes you cautious"]',1,'Cocaine causes aggressive driving, overconfidence, and impaired judgement.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of sleeping pills on driving?','["No effect","Drowsiness that can last into the next day","Improves alertness","Better focus"]',1,'Sleeping pills can cause drowsiness lasting into the next day. Do not drive if affected.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of antihistamines on driving?','["No effect","Can cause drowsiness and slow reactions","Improves driving","Better focus"]',1,'Some antihistamines cause drowsiness. Choose non-drowsy versions if you need to drive.',2,true),
    (5,2,'alcohol-driving','multiple_choice','Can cough medicine affect your driving?','["No","Yes — many contain alcohol or cause drowsiness","Only if expired","Only liquid forms"]',1,'Yes. Many cough medicines contain alcohol or antihistamines that cause drowsiness.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of combining drugs and alcohol?','["Safe","Dangerous — effects multiply, not add","No different","Only slightly worse"]',1,'Combining drugs and alcohol multiplies the effects. Extremely dangerous and unpredictable.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is khat and does it affect driving?','["A food","A stimulant plant that impairs judgement and alertness","A medicine","A drink"]',1,'Khat is a stimulant plant chewed in parts of Nigeria. It impairs judgement and can cause reckless driving.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of tramadol on driving?','["No effect","Drowsiness, dizziness, and impaired coordination","Improves focus","Better alertness"]',1,'Tramadol causes drowsiness, dizziness, and impaired coordination. Do not drive when taking it.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of codeine on driving?','["No effect","Drowsiness and impaired reaction time","Improves driving","Better focus"]',1,'Codeine causes drowsiness and slows reaction time. Do not drive when taking it.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of marijuana on reaction time?','["Faster","Slower","No effect","Improved"]',1,'Marijuana slows reaction time and impairs motor coordination.',2,true),
    (5,2,'alcohol-driving','multiple_choice','Can drug driving be detected?','["No","Yes — through blood, urine, and saliva tests","Only with breathalyser","Only by observation"]',1,'Drug driving can be detected through blood, urine, and saliva tests.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the penalty for drug driving in Nigeria?','["Warning","Fine, imprisonment, or both","No penalty","Only license suspension"]',1,'Drug driving carries the same penalties as drink driving: fine, imprisonment, or both.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What should you do if your medication causes drowsiness?','["Drive anyway","Do not drive — ask your doctor for alternatives","Drive slowly","Drive only short distances"]',1,'Do not drive. Ask your doctor about non-drowsy alternatives.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of sedatives on driving?','["No effect","Extreme drowsiness and slowed reactions","Improves focus","Better driving"]',1,'Sedatives cause extreme drowsiness and significantly slowed reactions.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of stimulants on driving?','["Safe","Overconfidence, aggressive driving, then sudden crash","Improved driving","Better focus"]',1,'Stimulants cause overconfidence and aggressive driving, followed by a sudden crash in alertness.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of hallucinogens on driving?','["No effect","Distorted perception — extremely dangerous","Improved driving","Better focus"]',1,'Hallucinogens distort perception of reality. Driving is extremely dangerous.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of inhalants on driving?','["No effect","Dizziness, impaired judgement, and possible unconsciousness","Improved driving","Better focus"]',1,'Inhalants cause dizziness, impaired judgement, and can cause sudden unconsciousness.',3,true),
    (5,2,'alcohol-driving','multiple_choice','Can you drive after taking herbal supplements?','["Always safe","Check with a doctor — some can cause drowsiness","Never","Only at night"]',1,'Some herbal supplements cause drowsiness. Check with a doctor before driving.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of anxiety medication on driving?','["No effect","Drowsiness and slowed reactions","Improves driving","Better focus"]',1,'Anxiety medications can cause drowsiness and slow reactions. Check with your doctor.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What should you tell your doctor about driving?','["Nothing","Tell them you drive so they can prescribe safe medication","Only if asked","Nothing relevant"]',1,'Always tell your doctor you drive so they can prescribe medications that do not impair driving.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of painkillers on driving?','["All are safe","Some strong painkillers cause drowsiness","All improve driving","No effect"]',1,'Strong painkillers like opioids cause drowsiness and impair driving. Check labels.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of eye drops on driving?','["No effect","Some may cause blurred vision temporarily","Improves vision","Better driving"]',1,'Some eye drops cause temporary blurred vision. Wait before driving.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of diet pills on driving?','["No effect","Some contain stimulants that cause dizziness","Improves driving","Better focus"]',1,'Some diet pills contain stimulants that can cause dizziness and anxiety.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of energy drinks on driving?','["Safe","Short-term alertness followed by a crash","Improves driving permanently","No effect"]',1,'Energy drinks give short-term alertness but cause a crash in concentration later.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the safest way to handle medication and driving?','["Just drive","Read labels, ask your doctor, and do not drive if affected","Drive slowly","Drive only short distances"]',1,'Read labels, ask your doctor, and do not drive if the medication causes any impairment.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of mixing multiple medications?','["Safe","Can cause unexpected interactions and impairment","No different","Only slightly different"]',1,'Mixing medications can cause unexpected interactions. Always check with a pharmacist.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on medication?','["Safe","Can increase or change the effect of medication","No effect","Reduces side effects"]',1,'Alcohol can increase or alter the effect of medications. Dangerous combination.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is a side effect warning on medication?','["Decoration","A warning about effects that may impair driving","A marketing label","A dosage guide"]',1,'Side effect warnings tell you if the medication may cause drowsiness, dizziness, or other impairment.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What does "may cause drowsiness" on a label mean for drivers?','["Nothing","Do not drive after taking it","Drive carefully","Drive only in town"]',1,'If a label says may cause drowsiness, do not drive after taking it.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of methamphetamine on driving?','["Safe","Reckless driving, hallucinations, and eventual crash","Improves driving","Better focus"]',1,'Methamphetamine causes reckless driving, hallucinations, and eventual severe fatigue.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of heroin on driving?','["No effect","Extreme impairment, slow reactions, possible unconsciousness","Improves driving","Better focus"]',1,'Heroin causes extreme impairment, very slow reactions, and possible unconsciousness.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of LSD on driving?','["No effect","Hallucinations and distorted perception — extremely dangerous","Improves driving","Better focus"]',1,'LSD causes hallucinations and completely distorted perception. Driving is impossible safely.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of ecstasy (MDMA) on driving?','["No effect","Blurred vision, impaired judgement, and dehydration","Improves driving","Better focus"]',1,'MDMA causes blurred vision, impaired judgement, and dehydration. Dangerous for driving.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the safest approach to drugs and driving?','["Take drugs and drive carefully","Do not take any impairing substance before driving","Only take prescription drugs","Only take small amounts"]',1,'Do not take any impairing substance before driving. Zero tolerance is safest.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of nicotine on driving?','["No effect","Minimal effect but distraction from smoking is risky","Improves driving","Better focus"]',1,'Nicotine itself has minimal effect, but the act of smoking distracts from driving.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of kava on driving?','["No effect","Sedative effect — impairs driving","Improves driving","Better focus"]',1,'Kava has a sedative effect that impairs driving ability.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What should you do if you feel unwell after taking medication?','["Drive anyway","Do not drive — wait until you feel normal","Drive slowly","Drive only short distances"]',1,'Do not drive. Wait until the effects have worn off completely.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of antimalarial drugs on driving?','["All are safe","Some may cause dizziness or vivid dreams","All improve driving","No effect"]',1,'Some antimalarial drugs like mefloquine can cause dizziness and vivid dreams. Check with your doctor.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of diabetes medication on driving?','["No effect","Can cause low blood sugar — dizziness and confusion","Improves driving","Better focus"]',1,'Diabetes medication can cause hypoglycaemia (low blood sugar), leading to dizziness and confusion.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What should a diabetic driver carry?','["Nothing","Fast-acting sugar in case of low blood sugar","Extra medication","Water only"]',1,'Diabetic drivers should carry fast-acting sugar (glucose tablets, juice) in case of low blood sugar.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of blood pressure medication on driving?','["No effect","Some may cause dizziness, especially when standing","Improves driving","Better focus"]',1,'Some blood pressure medications cause dizziness, especially when standing up quickly.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of antidepressants on driving?','["No effect","Some may cause drowsiness or dizziness","Improves driving","Better focus"]',1,'Some antidepressants cause drowsiness or dizziness. Discuss with your doctor.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of muscle relaxants on driving?','["No effect","Drowsiness and impaired coordination","Improves driving","Better focus"]',1,'Muscle relaxants cause drowsiness and impair coordination. Do not drive when taking them.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of ADHD medication on driving?','["No effect","May improve focus in ADHD patients but can cause anxiety in others","Always impairs","Always improves"]',1,'ADHD medication may improve focus for those diagnosed, but can cause anxiety and restlessness in others.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the safest plan for a night out involving alcohol?','["Drive home slowly","Plan transport before drinking — taxi, designated driver, or public transport","Eat a big meal","Drink water between drinks"]',1,'Plan your transport before you start drinking. Never drive after drinking.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of age on alcohol tolerance?','["No effect","Older adults process alcohol more slowly","Improves with age","Younger people more affected"]',1,'Older adults process alcohol more slowly. The same amount has a stronger effect.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of gender on alcohol processing?','["No difference","Women generally process alcohol more slowly than men","Men process slower","Same for both"]',1,'Women generally have less body water and less of the enzyme that breaks down alcohol.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of empty stomach on alcohol absorption?','["Slower","Faster — alcohol absorbs more quickly","No difference","Only matters for wine"]',1,'Drinking on an empty stomach causes faster alcohol absorption. Eat before drinking.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of body weight on BAC?','["No effect","Lower weight = higher BAC for the same amount","Higher weight = higher BAC","No correlation"]',1,'Lower body weight generally results in a higher BAC for the same amount of alcohol.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of carbonated drinks on alcohol absorption?','["Slower","Faster — carbonation speeds absorption","No effect","Only for beer"]',1,'Carbonated mixers speed up alcohol absorption. Be cautious with fizzy drinks.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of fatigue combined with alcohol?','["No additional effect","Multiplies impairment — very dangerous","Reduces alcohol effect","Improves alertness"]',1,'Fatigue and alcohol multiply each other. Together they are far more dangerous than either alone.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the long-term effect of alcohol on driving ability?','["No effect","Chronic impairment of reflexes and judgement","Improves over time","Only affects new drivers"]',1,'Long-term alcohol use can chronically impair reflexes and judgement even when sober.',3,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on sleep quality?','["Improves","Disrupts sleep — poor rest means drowsy driving","No effect","Deepens sleep"]',1,'Alcohol disrupts sleep quality. Poor sleep leads to drowsy driving the next day.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the safest Blood Alcohol Concentration for driving?','["0.05%","0.02%","0.00%","0.08%"]',2,'Zero. Nigeria has zero tolerance. Any alcohol impairs driving ability.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on decision-making?','["Improves it","Impairs — leads to risky choices like speeding","No effect","Better decisions"]',1,'Alcohol impairs decision-making, leading to risky choices like speeding and overtaking dangerously.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on tracking a moving object?','["Improves","Impairs — difficulty staying in lane","No effect","Better tracking"]',1,'Alcohol impairs the ability to track moving objects and maintain lane position.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on divided attention tasks?','["Improves","Impairs — cannot handle multiple inputs","No effect","Better multitasking"]',1,'Alcohol severely impairs divided attention. Cannot process multiple driving inputs simultaneously.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the safest advice for any driver regarding alcohol?','["One drink is fine","If you drink, do not drive. If you drive, do not drink","Only drink at home","Only drink beer"]',1,'If you drink, do not drive. If you drive, do not drink. Simple and saves lives.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of peer pressure on drink driving?','["No effect","Can push drivers to drink and drive — resist it","Improves decisions","Only affects young drivers"]',1,'Peer pressure can push drivers to drink and drive. Always resist and plan ahead.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on night driving?','["No additional effect","Compounds reduced visibility with impaired vision","Improves night vision","Better focus"]',1,'Alcohol compounds the challenges of night driving with impaired vision and slower reactions.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on new drivers?','["Same as experienced","More dangerous — less experience to compensate","Less effect","No effect"]',1,'New drivers are more affected. They lack the experience to compensate for impairment.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on older drivers?','["Less effect","More affected — slower metabolism and medications","No effect","Improves driving"]',1,'Older drivers are more affected due to slower metabolism and potential medication interactions.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the most common time for drink driving accidents?','["Morning rush hour","Late night and early morning (midnight to 3am)","Afternoon","Evening rush hour"]',1,'Most drink driving accidents occur between midnight and 3am.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on motorcyclists?','["Less than car drivers","More dangerous — balance and coordination critical","No effect","Same as car drivers"]',1,'Motorcyclists are more affected. Balance and coordination are critical and easily impaired.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on commercial drivers?','["Less risk","More dangerous — long hours plus impairment","No effect","Same as private drivers"]',1,'Commercial drivers face compounded risk from long hours and alcohol. Very dangerous.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What should you do if a friend wants to drink and drive?','["Let them","Take their keys, arrange safe transport","Report to police only","Nothing"]',1,'Take their keys and arrange safe transport. You could save their life.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol tolerance on BAC?','["Lower BAC","BAC is the same regardless of tolerance","Higher BAC","No BAC"]',1,'Tolerance may mask the feeling of being drunk, but BAC is the same. You are still impaired.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on risk-taking?','["Reduces risk-taking","Increases risk-taking behaviour","No effect","Makes you cautious"]',1,'Alcohol increases risk-taking behaviour. Drivers take chances they would not take sober.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the safest way to celebrate and get home?','["Drive slowly","Use a taxi, ride-hailing, or designated driver","Walk on the highway","Take a bus if available"]',1,'Use a taxi, ride-hailing service, or designated driver. Never drink and drive.',1,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on pedestrian safety?','["No effect","Impairs judgement — pedestrians may walk into traffic","Improves awareness","Better decisions"]',1,'Alcohol also impairs pedestrians. Drunk pedestrians are at high risk of being hit.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on seatbelt use?','["More likely to wear","Less likely to wear a seatbelt","No effect","Always wears"]',1,'Drink drivers are less likely to wear seatbelts, increasing injury severity.',2,true),
    (5,2,'alcohol-driving','multiple_choice','What is the effect of alcohol on speed choice?','["Drives slower","Tends to drive faster","No effect","Always speed limit"]',1,'Drink drivers tend to drive faster than sober drivers. Combined with impaired reactions, this is deadly.',2,true);
